import java.io.*
import java.util.*

class Fibonacci(private val mod: Long) {
    private val calculatedNumbers: MutableMap<Long, Long> = mutableMapOf(0L to 1L, 1L to 1L)

    fun fib(n: Long): Long {
        return calculatedNumbers.getOrPut(n) {
            val k = n / 2
            if (n % 2 == 0L) {
                (fib(k) * fib(k) + fib(k - 1) * fib(k - 1)) % mod
            } else {
                (fib(k) * fib(k + 1) + fib(k - 1) * fib(k)) % mod
            }
        }
    }
}

object Exponentiation {
    fun calc(a: Long, b: Long, m: Long): Long {
        return when {
            b == 0L -> 1L
            b == 1L -> a % m
            b % 2 == 0L -> calc((a * a) % m, b / 2, m)
            else -> a * calc((a * a) % m, (b - 1) / 2, m) % m
        }
    }
}

class Solver {
    private var n: Long = 0
    private var k: Long = 0
    private var l: Long = 0
    private var MOD: Long = 0

    fun read(in: InputReader) {
        n = in.nextLong()
        k = in.nextLong()
        l = in.nextLong()
        MOD = in.nextLong()
    }

    fun solve(in: InputReader, out: PrintWriter) {
        read(in)
        if (l != 64 && (1L shl l) - 1 < k) {
            out.println(0)
            return
        }

        val zeroPos = Fibonacci(MOD).fib(n + 1)
        var onePos = Exponentiation.calc(2, n, MOD) - zeroPos
        while (onePos < 0) onePos += MOD

        var res = 1L
        for (i in 0 until l.toInt()) {
            if ((k and (1L shl i)) != 0L) res *= onePos
            else res *= zeroPos
            res %= MOD
        }
        out.println(res % MOD)
    }
}

class InputReader(private val reader: BufferedReader) {
    private var currentLine: Array<String> = emptyArray()
    private var token = 0

    constructor(stream: InputStream) : this(BufferedReader(InputStreamReader(stream), 32768))

    fun next(): String {
        while (currentLine.isEmpty() || token >= currentLine.size) {
            try {
                val line = reader.readLine()
                if (line == null) return ""
                currentLine = line.split("\\s+".toRegex()).toTypedArray()
                token = 0
            } catch (e: IOException) {
                e.printStackTrace()
            }
        }
        return currentLine[token++]
    }

    fun nextInt(): Int = next().toInt()

    fun nextLong(): Long = next().toLong()
}

fun main() {
    val in = InputReader(System.`in`)
    val out = PrintWriter(System.out)
    Solver().solve(in, out)
    out.close()
}

